import React from 'react';
import hero from './images/Hero Banner.jpg'
import NavigationBar from './components/NavigationBar';
// import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <NavigationBar />
      </header>
      <body>
        <img src={hero} className="App-logo" alt="logo"/>
      </body>
    </div>
  );
}

export default App;
